module concatenated_nba_alignment(input logic clock, row_select,
                                  input logic signed [5:0] left_start, right_end,
                                  input logic [7:0] packet);
  logic [7:-4] left_bank[2];
  logic [1:12] right_bank[2];

  always @(posedge clock) begin : schedule_update
    logic row;
    logic signed [5:0] first_pos, second_pos;
    logic [7:0] saved_packet;
    left_bank[0] <= 12'ha54;
    left_bank[1] <= 12'h627;
    right_bank[0] <= 12'hd31;
    right_bank[1] <= 12'h8e6;

    row = row_select;
    first_pos = left_start;
    second_pos = right_end;
    saved_packet = packet;
    {left_bank[row][first_pos+:4], right_bank[!row][second_pos-:4]} <= saved_packet;
    row = !row;
    first_pos = 0;
    second_pos = 4;
    saved_packet = 0;
  end


  function automatic logic [11:0] patch_left(
    input logic [11:0] seed, input int low, input logic [3:0] bits
  );
    patch_left = seed;
    for (int physical = 0; physical < 12; physical++)
      if (physical - 4 >= low && physical - 4 < low + 4)
        patch_left[physical] = bits[physical - 4 - low];
  endfunction

  function automatic logic [11:0] patch_right(
    input logic [11:0] seed, input int high, input logic [3:0] bits
  );
    patch_right = seed;
    for (int physical = 0; physical < 12; physical++)
      if (12 - physical <= high && 12 - physical > high - 4)
        patch_right[physical] = bits[high - (12 - physical)];
  endfunction

  logic started = 0;
  logic [11:0] left_0, left_1, right_0, right_1;
  always @(posedge clock) begin
    if (started) begin
      assert(left_bank[0] == left_0);
      assert(left_bank[1] == left_1);
      assert(right_bank[0] == right_0);
      assert(right_bank[1] == right_1);
    end
    started <= 1;
    left_0 <= row_select ? 12'ha54 : patch_left(12'ha54, int'(left_start), packet[7:4]);
    left_1 <= row_select ? patch_left(12'h627, int'(left_start), packet[7:4]) : 12'h627;
    right_0 <= row_select ? patch_right(12'hd31, int'(right_end), packet[3:0]) : 12'hd31;
    right_1 <= row_select ? 12'h8e6 : patch_right(12'h8e6, int'(right_end), packet[3:0]);
  end
endmodule
